// Generated by `manage.py bazis_front screens` from spec/screens/:
// never edit it, change the specs and generate it again.

/** The route of each screen of the specs by its id. */
export const SCREENS = {
  'draft-tasks': '/drafts',
  home: '/',
  'task-board': '/board',
  'task-calendar': '/calendar',
  'task-card': '/tasks/:id',
  'task-list': '/tasks',
} as const;

/** The route of a screen; that of an item for a screen of an item (`:id` in its route). */
export function routeTo(screen: keyof typeof SCREENS, id?: string): string {
  const route: string = SCREENS[screen];
  return id === undefined ? route : route.replace(':id', encodeURIComponent(id));
}
